def _load_appendix():
    p = "/home/user/majestic-goverment-reform/Проекты изменений/01а_Приложение_ГК.md"
    s = open(p, encoding="utf-8").read()
    i = s.find("Раздел IV. Обязательственное право")
    assert i != -1, "appendix start not found"
    s = s[i:]
    s = re.sub(r"^\s*#{1,6}\s*", "", s, flags=re.M)
    s = s.replace("\r", "")
    s = re.sub(r"\n{3,}", "\n\n", s).strip()
    return s
